// Every React component is just a function
// that returns JSX (HTML-like syntax)
function Greeting() {
  return (
    <div>
      <h1>Hello, World!</h1>
      <p>Welcome to React</p>
    </div>
  );
}

// Render it to the page
// ReactDOM.createRoot(document.getElementById('root')).render(<Greeting />);

function Profile() {
  const name = 'Alice';
  const isAdmin = true;
  const scores = [95, 87, 92];

  return (
    // 1. Must return a single root element (or Fragment)
    <>
      {/* 2. Comments use curly braces */}

      {/* 3. class → className */}
      <div className="profile-card">

        {/* 4. Embed JS expressions with curly braces */}
        <h2>{name}</h2>

        {/* 5. for → htmlFor on labels */}
        <label htmlFor="email">Email</label>

        {/* 6. Conditional rendering */}
        {isAdmin && <span className="badge">Admin</span>}

        {/* 7. Self-closing tags are required */}
        <input type="email" id="email" />

        {/* 8. Inline styles use objects */}
        <p style={{ color: 'red', fontSize: '14px' }}>Danger</p>

        {/* 9. Map arrays to elements */}
        <ul>
          {scores.map((score, i) => <li key={i}>{score}</li>)}
        </ul>
      </div>
    </>
  );
}

// Define a reusable card component
function CourseCard({ title, description, difficulty, xp }) {
  return (
    <div className="card">
      <h3>{title}</h3>
      <p>{description}</p>
      <span className={`badge badge--${difficulty}`}>{difficulty}</span>
      <span className="xp">{xp} XP</span>
    </div>
  );
}

// Use it with different data
function App() {
  return (
    <div className="grid">
      <CourseCard
        title="Python Basics"
        description="Learn Python from scratch"
        difficulty="beginner"
        xp={50}
      />
      <CourseCard
        title="React Hooks"
        description="Master modern React"
        difficulty="intermediate"
        xp={80}
      />
    </div>
  );
}

// Default parameter values as defaults
function Button({ label = 'Click me', variant = 'primary', disabled = false }) {
  return (
    <button className={`btn btn--${variant}`} disabled={disabled}>
      {label}
    </button>
  );
}

// A generic Card wrapper
function Card({ children, className = '' }) {
  return (
    <div className={`card ${className}`}>
      {children}
    </div>
  );
}

// Use it to wrap any content
function App() {
  return (
    <>
      <Card className="card--featured">
        <h2>Python for Beginners</h2>
        <p>Start your coding journey</p>
        <button>Enroll Now</button>
      </Card>

      <Card>
        <img src="avatar.jpg" alt="User" />
        <h3>Alice Johnson</h3>
      </Card>
    </>
  );
}

const courses = [
  { id: 1, title: 'HTML', level: 'Beginner' },
  { id: 2, title: 'CSS', level: 'Beginner' },
  { id: 3, title: 'React', level: 'Intermediate' },
];

function CourseList() {
  return (
    <ul>
      {courses.map(course => (
        // key must be a stable, unique identifier
        <li key={course.id}>
          <strong>{course.title}</strong> — {course.level}
        </li>
      ))}
    </ul>
  );
}
